arguments.command:
mkdir -p notes
cat > notes/PRC-412.md <<'E'
# PRC-412
Cause: f02b252 changed `x*90/100` to `(x*90+99)/100` (round up) in bin/price, bin/quote, lib/invoice.sh. Spec: 10% off, rounded down.
Plan: restore floor division in all three (same defect, must agree); add tests first.
E
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash -c 'source lib/invoice.sh' _ 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo rc=$?

